import java.nio.file.*;import java.io.*;import brut.androlib.src.SmaliBuilder;import com.android.tools.smali.dexlib2.Opcodes;import com.android.tools.smali.dexlib2.writer.builder.DexBuilder;import com.android.tools.smali.dexlib2.writer.io.FileDataStore;public class AssembleSmali{public static void main(String[]a)throws Exception{Path p=Paths.get(a[0]);SmaliBuilder b=new SmaliBuilder(p.toFile(),28);DexBuilder d=new DexBuilder(new Opcodes(28,0));try(var fs=Files.walk(p)){for(Path f:(Iterable<Path>)fs.filter(f->f.toString().endsWith(".smali"))::iterator)b.buildFile(p.relativize(f).toString(),d);}d.writeTo(new FileDataStore(new File(a[1])));}}